sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var SCOPE = 'x_2223823_apollo_0';
    var ITEM_NAME = 'Lab Test Request';
    var RESULT_TABLE = SCOPE + '_lab_test_result';

    // Run only for the Lab Test Request catalog item.
    if (current.cat_item.getDisplayValue() != ITEM_NAME) {
        return;
    }

    // Read catalog variables by their variable names.
    function getVar(names) {
        for (var i = 0; i < names.length; i++) {
            var v = current.variables[names[i]];

            if (v !== undefined && v !== null &&
                v.toString() !== '') {
                return v.toString();
            }

            var scoped = current.variables[SCOPE + '_' + names[i]];

            if (scoped !== undefined && scoped !== null &&
                scoped.toString() !== '') {
                return scoped.toString();
            }
        }

        return '';
    }

    // Prevent duplicate Lab Test Result records.
    var dup = new GlideRecord(RESULT_TABLE);
    dup.addQuery('request', current.getUniqueValue());
    dup.setLimit(1);
    dup.query();

    if (dup.next()) {
        return;
    }

    // Read catalog variables.
    var patient = getVar(['patient']);
    var labTest = getVar(['lab_test']);
    var hospital = getVar(['hospital']);
    var equipment = getVar(['required_equipment']);

    // Priority: Urgent = true; Routine or empty = false.
    var urgent = false;
    var priority = current.variables['priority'];

    if (priority !== undefined && priority !== null) {
        var priorityLabel = '';

        if (typeof priority.getDisplayValue === 'function') {
            priorityLabel = priority.getDisplayValue();
        }

        var priorityValue = priority.toString();

        urgent = (
            priorityLabel.toLowerCase() == 'urgent' ||
            priorityValue.toLowerCase() == 'urgent'
        );
    }

    // Find the Requested choice value for the result table.
    var statusValue = '';

    var choice = new GlideRecord('sys_choice');
    choice.addQuery('name', RESULT_TABLE);
    choice.addQuery('element', 'status');
    choice.addQuery('label', 'Requested');
    choice.addQuery('inactive', false);
    choice.setLimit(1);
    choice.query();

    if (choice.next()) {
        statusValue = choice.getValue('value');
    }

    // Validate mandatory values.
    var missing = [];

    if (!patient) {
        missing.push('Patient');
    }

    if (!labTest) {
        missing.push('Lab Test');
    }

    if (!hospital) {
        missing.push('Hospital');
    }

    if (!statusValue) {
        missing.push('Requested status choice');
    }

    if (missing.length > 0) {
        gs.error(
            'FL-04: Lab Test Result not created for ' +
            current.getValue('number') +
            '. Missing: ' + missing.join(', ')
        );
        return;
    }

    // Create Lab Test Result.
    var result = new GlideRecord(RESULT_TABLE);
    result.initialize();

    result.setValue('request', current.getUniqueValue());
    result.setValue('patient', patient);
    result.setValue('hospital', hospital);
    result.setValue('lab_test', labTest);
    result.setValue('status', statusValue);
    result.setValue('urgent', urgent);

    // Copy Required Equipment when a value was selected.
    if (equipment) {
        result.setValue('equipment', equipment);
    }

    var resultId = result.insert();

    if (!resultId) {
        gs.error(
            'FL-04: Could not create Lab Test Result for ' +
            current.getValue('number')
        );
        return;
    }

    // Notify lab team; notify doctor for urgent requests.
    gs.eventQueue(
        SCOPE + '.lab_request_created',
        result,
        result.getValue('hospital'),
        ''
    );

    if (urgent) {
        gs.eventQueue(
            SCOPE + '.lab_urgent_request',
            result,
            result.getValue('patient'),
            ''
        );
    }

})(current, previous);
